insert into public.recipes
    (slug, title, emoji, description, total_minutes, difficulty, servings, published,
     source_name, source_url, license_name, attribution, modified_from_source)
values
    ('wikibooks_cucumber_and_tomato_salad', 'Cucumber and Tomato Salad', '🥗', 'This salad is very easy to make.', 10, 'Very easy', 2, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ACucumber+and+Tomato+Salad&oldid=4518124', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_szegedin_goulash', 'Szegedin Goulash', '🍽️', 'Szegedin goulash is a variety of goulash that adds sauerkraut and sour cream to the traditional ingredients. Most people believe that the name "Szegedin Goulash" derives from Szeged, a town in Hungary. But in fact,...', 100, 'Medium', 4, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ASzegedin+Goulash&oldid=4512108', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_garlic_shrimp_scampi_pasta', 'Garlic Shrimp Scampi Pasta', '🍝', 'This garlic shrimp scampi recipe is adapted from the YouTube channel Tasty.', 15, 'Easy', 4, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AGarlic+Shrimp+Scampi+Pasta&oldid=4510113', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_tiramisu', 'Tiramisù', '🍳', 'Tiramisù means "cheer me up" in Italian and aptly describes this dessert traditionally made from savoiardi or ladyfingers or sponge cake, espresso coffee, mascarpone cheese, egg whites, yolk and sugar. The biscuits...', 75, 'Easy', 6, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ATiramis%C3%B9&oldid=4608624', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_microwave_risotto', 'Microwave Risotto', '🍚', 'Microwave risotto is made using the microwave. It requires very little stirring and turns out quite well.', 40, 'Easy', 3, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AMicrowave+Risotto&oldid=4517962', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_strawberry_and_yogurt_eton_mess', 'Strawberry and Yogurt Eton Mess', '🍽️', 'Eton mess is a dessert of English origin consisting of a mixture of strawberries, pieces of meringue and cream, which is traditionally served at Eton College''s annual prize-giving celebration picnic on the "Fourth of...', 10, 'Very easy', 4, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AStrawberry+and+Yogurt+Eton+Mess&oldid=4587373', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_pastries_filled_with_jam_marmeladetascherl', 'Pastries Filled with Jam (Marmeladetascherl)', '🍳', 'The marmeladetascherl have their origins in those times; so just try them and get a taste of former times in the Pinzgau region.', 30, 'Easy', 4, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3APastries+Filled+with+Jam+%28Marmeladetascherl%29&oldid=4587212', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_lentil_and_sausage_stew', 'Lentil and Sausage Stew', '🍲', 'This lentil and sausage stew is intended for eating with spätzle. It is a slightly modified recipe; the traditional one has no tomato and honey. But, as with many "national meals," there are different opinions. Try...', 60, 'Medium', 2, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ALentil+and+Sausage+Stew&oldid=4518638', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_caponata_sicilian_eggplant_and_vegetables', 'Caponata (Sicilian Eggplant and Vegetables)', '🍳', 'Caponata is a Sicilian eggplant dish consisting of cooked vegetables with chopped up fried eggplant, celery, sweetened vinegar, and capers with sweet sauce.', 60, 'Easy', 2, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ACaponata+%28Sicilian+Eggplant+and+Vegetables%29&oldid=4508143', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_coronation_chicken', 'Coronation Chicken', '🍛', 'Coronation chicken was apparently created by Florist Constance Spry and Rosemary Hume for the banquet of the coronation of Queen Elizabeth II in 1953—see Wikipedia''s article on Coronation Chicken for more...', 45, 'Medium', 8, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ACoronation+Chicken&oldid=4517533', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_sylheti_beef_curry', 'Sylheti Beef Curry', '🍛', '| Beef recipes | Cuisine of India | Cuisine of Sylhet', 120, 'Medium', 4, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ASylheti+Beef+Curry&oldid=4517567', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_spaghetti_alla_puttanesca', 'Spaghetti alla Puttanesca', '🍝', 'Ingredients vary a bit among chefs and cooks according to individual tastes. However, this version (from Lazio) always includes anchovies, while a Neapolitan version never does. An Italian-American version of this...', 20, 'Easy', 6, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ASpaghetti+alla+Puttanesca&oldid=4622379', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_dinuguan_pork_blood_stew', 'Dinuguan (Pork Blood Stew)', '🍲', 'Dinuguan (pork blood stew) or dinardaraan in Ilocano is a Filipino dish usually made from the blood, entrails and meat of a pig. It is sometimes known as "chocolate meat" as the stew has a thick chocolate-like color...', 120, 'Easy', 10, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ADinuguan+%28Pork+Blood+Stew%29&oldid=4518602', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_mozzarella_sticks', 'Mozzarella Sticks', '🍞', 'The following is a recipe on how to make breaded mozzarella sticks.', 20, 'Medium', 1, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AMozzarella+Sticks&oldid=4517757', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true)
on conflict (slug) do update set
    title = excluded.title,
    emoji = excluded.emoji,
