insert into public.recipe_steps (recipe_id, step_number, instruction)
select r.id, v.step_number, v.instruction
from (values
    ('wikibooks_cucumber_and_tomato_salad', 1, 'Chop cucumbers and tomatoes into small cubes (approx. ¼ inch on the side).'),
    ('wikibooks_cucumber_and_tomato_salad', 2, 'Peel and chop the onion.'),
    ('wikibooks_cucumber_and_tomato_salad', 3, 'Combine all of the above in an appropriately sized bowl.'),
    ('wikibooks_cucumber_and_tomato_salad', 4, 'Add sunflower oil and mix well.'),
    ('wikibooks_cucumber_and_tomato_salad', 5, 'Add salt to taste and mix again.'),
    ('wikibooks_szegedin_goulash', 1, 'Heat the lard in a pot, then add the pork and sauté it for about 3 minutes. Take out the pork and set it aside on a plate.'),
    ('wikibooks_szegedin_goulash', 2, 'Put the finely chopped onions into the casserole and fry until they become golden brown.'),
    ('wikibooks_szegedin_goulash', 3, 'Stir in the tomato purée and paprika, and add some water or stock. Then add the meat, bay leaves and garlic; pour in more water or stock and season with salt and pepper. Reduce the heat and cook for about 30 minutes.'),
    ('wikibooks_szegedin_goulash', 4, 'Add the sauerkraut, and cook for another 40 minutes.'),
    ('wikibooks_szegedin_goulash', 5, 'Add the sour cream, mix it thoroughly with the goulash, and serve it on warm plates.'),
    ('wikibooks_garlic_shrimp_scampi_pasta', 1, 'Boil the spaghetti in water until al dente.'),
    ('wikibooks_garlic_shrimp_scampi_pasta', 2, 'Meanwhile, melt the butter in a pan over medium heat.'),
    ('wikibooks_garlic_shrimp_scampi_pasta', 3, 'Add the garlic and stir.'),
    ('wikibooks_garlic_shrimp_scampi_pasta', 4, 'Add the shrimp and cook for 6 minutes, stirring occasionally, until they turn pink-red in color.'),
    ('wikibooks_garlic_shrimp_scampi_pasta', 5, 'Season with salt and pepper, then stir in lemon juice, chili, and parsley.'),
    ('wikibooks_garlic_shrimp_scampi_pasta', 6, 'Drain the pasta in a colander and stir into the pan of shrimp.'),
    ('wikibooks_garlic_shrimp_scampi_pasta', 7, 'Divide the pasta between 4 plates and serve.'),
    ('wikibooks_tiramisu', 1, 'Make espresso coffee, and let it cool a bit.'),
    ('wikibooks_tiramisu', 2, 'Separate the egg yolks and the whites of two eggs in two bowls.'),
    ('wikibooks_tiramisu', 3, 'Beat sugar into the egg yolks.'),
    ('wikibooks_tiramisu', 4, 'Beat the mascarpone into the sweetened yolks.'),
    ('wikibooks_tiramisu', 5, 'Add two more egg whites to the other two and whip until they form stiff peaks.'),
    ('wikibooks_tiramisu', 6, 'Gently fold egg whites into mascarpone mixture.'),
    ('wikibooks_tiramisu', 7, 'Quickly dip both sides of the ladyfingers in the espresso.'),
    ('wikibooks_tiramisu', 8, 'Layer soaked ladyfingers and mascarpone in a large bowl or pan (start with fingers, finish with mascarpone).'),
    ('wikibooks_tiramisu', 9, 'Refrigerate for one hour or two.'),
    ('wikibooks_tiramisu', 10, 'Sprinkle unsweetened cocoa powder on top just before to serve.'),
    ('wikibooks_microwave_risotto', 1, 'In a saucepan, bring chicken broth, salt and pepper to a low simmer, and keep warm until needed.'),
    ('wikibooks_microwave_risotto', 2, 'In an oven-proof dish (or 10-inch/25 cm quiche dish), heat oil and butter in microwave for 2 minutes.'),
    ('wikibooks_microwave_risotto', 3, 'Add minced onion to the dish, stir to coat with oil, and cook in microwave for 4 minutes.'),
    ('wikibooks_microwave_risotto', 4, 'Add uncooked rice to the dish, stir to coat with oil, and cook in microwave for another 4 minutes.'),
    ('wikibooks_microwave_risotto', 5, 'Pour simmering chicken broth into the dish and stir well. Microwave 9 minutes.'),
    ('wikibooks_microwave_risotto', 6, 'Stir rice and chicken broth well and microwave another 9 minutes.'),
    ('wikibooks_microwave_risotto', 7, 'If a creamier risotto is desired, add ¼ cup () warm water, stir well and microwave for another 2 minutes.'),
    ('wikibooks_strawberry_and_yogurt_eton_mess', 1, 'Rinse the strawberries, remove the tops, and cut into halves.'),
    ('wikibooks_strawberry_and_yogurt_eton_mess', 2, 'Break the meringues into pieces (not too small) and place into a bowl.'),
    ('wikibooks_strawberry_and_yogurt_eton_mess', 3, 'Put the double cream, vanilla essence, and icing sugar into a bowl. Whip until reasonably stiff.'),
    ('wikibooks_strawberry_and_yogurt_eton_mess', 4, 'Combine the whipped cream, yoghurt, strawberries, and meringue, being careful not to mash the meringue into pieces that are too small.'),
    ('wikibooks_strawberry_and_yogurt_eton_mess', 5, 'Serve in bowls.'),
    ('wikibooks_pastries_filled_with_jam_marmeladetascherl', 1, 'Mix the flour with the baking powder, and rub in the butter. Then, add the curd and the salt, and knead it into dough.'),
    ('wikibooks_pastries_filled_with_jam_marmeladetascherl', 2, 'Let the dough rest in the fridge for 1 hour.'),
    ('wikibooks_pastries_filled_with_jam_marmeladetascherl', 3, 'Roll the dough to about 2 mm thick, and cut it into 10 cm squares.'),
    ('wikibooks_pastries_filled_with_jam_marmeladetascherl', 4, 'Put a blob of jam in the middle of each square, and fold them diagonally. Press the edges to seal the tascherl.'),
    ('wikibooks_pastries_filled_with_jam_marmeladetascherl', 5, 'Brush a bit of the egg white onto each tascherl, and place onto a baking sheet.'),
    ('wikibooks_pastries_filled_with_jam_marmeladetascherl', 6, 'Preheat the oven to 180°C, put the tascherl into the oven, and bake them for approximately 20 minutes.'),
    ('wikibooks_pastries_filled_with_jam_marmeladetascherl', 7, 'Before serving, dust some sugar onto the tascherl to add some extra flavour.'),
    ('wikibooks_lentil_and_sausage_stew', 1, 'Wash the lentils in sieve and cook them over low heat in the 1 litre of water for 40–50 minutes.'),
    ('wikibooks_lentil_and_sausage_stew', 2, 'About 20 minutes before the end of the cooking, add the carrot, onion, potatoes, garlic, sausages, bay leaf, and pork belly.'),
    ('wikibooks_lentil_and_sausage_stew', 3, 'After cooking, put the pot on the side and keep it warm.'),
    ('wikibooks_lentil_and_sausage_stew', 4, 'Melt the butter in the little pot, add the flour, and cook carefully until brown, stirring the whole time.'),
    ('wikibooks_lentil_and_sausage_stew', 5, 'Slowly and gradually add the ⅓ litre water, and bring to a boil.'),
    ('wikibooks_lentil_and_sausage_stew', 6, 'Add the tomato paste, vinegar, and honey. Season with salt and pepper to your liking.'),
    ('wikibooks_lentil_and_sausage_stew', 7, 'Stir the sauce into the lentils, mix well, and keep warm.'),
    ('wikibooks_caponata_sicilian_eggplant_and_vegetables', 1, 'Strip the filaments from the celery sticks and blanch in lightly salted water for five minutes. Drain and cut the celery into bite-size pieces, sauté them in a little oil, and set aside.'),
    ('wikibooks_caponata_sicilian_eggplant_and_vegetables', 2, 'Wash and dice the eggplant, strain, and sprinkle liberally with salt, and let sit for several hours to draw out the bitterness. In the meantime, blanch, peel, seed and chop the tomatoes.'),
    ('wikibooks_caponata_sicilian_eggplant_and_vegetables', 3, 'Once the eggplant has sat, rinse away the salt and pat the pieces dry. Finely slice the onion and sauté them in olive oil; once they have turned translucent, add the capers, pine nuts, olives, and tomatoes. Continue cooking, stirring with a wooden spoon, until the tomatoes are done, about 15 minutes, and then remove the pot from the heat.'),
    ('wikibooks_caponata_sicilian_eggplant_and_vegetables', 4, 'While the tomatoes are cooking, heat another pan of oil and fry the eggplant, in batches, to prevent lowering of the frying temperature. When the last batch is done, return the tomato pot to the heat and stir in the eggplant together with the previously sautéed celery. Cook for several minutes over low flame, stirring gently, then stir in the vinegar and the sugar; when the vinegar has almost completely evaporated, remove the pot from the fire and let it cool.'),
    ('wikibooks_caponata_sicilian_eggplant_and_vegetables', 5, 'Serve the caponata cold with a garnish of fresh basil. Caponata keeps for several days in the refrigerator.'),
    ('wikibooks_coronation_chicken', 1, 'Skin the chicken if needed, and cut it into small pieces. Traditionally the chicken is cooked whole in advance, but alternatively you can use raw chicken and grill the chicken pieces at this point.'),
    ('wikibooks_coronation_chicken', 2, 'In a small saucepan, warm a small amount of vegetable oil.'),
    ('wikibooks_coronation_chicken', 3, 'Add the onion to the pan and cook gently until soft (about 3 minutes).'),
    ('wikibooks_coronation_chicken', 4, 'Add the curry paste, tomato puree, wine, bay leaf and lemon juice. Simmer uncovered for about 10 minutes until well-reduced. Strain and leave to cool.'),
    ('wikibooks_coronation_chicken', 5, 'Purée the chopped apricots in a blender or processor. Beat the cooled sauce into the mayonnaise with the apricot purée.'),
    ('wikibooks_coronation_chicken', 6, 'Whip the cream to stiff peaks, and fold into the mixture.'),
    ('wikibooks_coronation_chicken', 7, 'Season with salt and pepper, and a little lemon juice if necessary.'),
    ('wikibooks_coronation_chicken', 8, 'Fold in the chicken pieces, garnish with watercress, and serve.'),
    ('wikibooks_sylheti_beef_curry', 1, 'Heat the vegetable oil in a large, heavy-bottomed pan over medium heat.'),
    ('wikibooks_sylheti_beef_curry', 2, 'Add the cloves, green cardamom pods, cinnamon stick, and bay leaves. Sauté for a minute until fragrant.'),
    ('wikibooks_sylheti_beef_curry', 3, 'Add the chopped onions and sauté until they turn golden brown.'),
    ('wikibooks_sylheti_beef_curry', 4, 'Add the ginger-garlic paste and sauté for another 2 minutes until the raw smell disappears.'),
    ('wikibooks_sylheti_beef_curry', 5, 'Add the beef cubes and cook until they are browned on all sides.'),
    ('wikibooks_sylheti_beef_curry', 6, 'Stir in the cumin powder, coriander powder, turmeric powder, and chili powder. Cook for a couple of minutes to toast the spices.'),
    ('wikibooks_sylheti_beef_curry', 7, 'Add the hatxora, chopped tomatoes and green chilies. Cook until the tomatoes are soft and the oil starts to separate from the mixture.'),
    ('wikibooks_sylheti_beef_curry', 8, 'Pour in enough water to cover the beef, season with salt, and bring to a boil.'),
    ('wikibooks_sylheti_beef_curry', 9, 'Reduce the heat to low, cover the pan, and let the curry simmer for about 1.5–2 hours or until the beef is tender and the flavors meld.'),
    ('wikibooks_sylheti_beef_curry', 10, 'Garnish with fresh coriander leaves and serve hot with steamed rice or naan.'),
    ('wikibooks_spaghetti_alla_puttanesca', 1, 'Put the olive oil, garlic, and anchovy paste in a skillet over medium heat.'),
    ('wikibooks_spaghetti_alla_puttanesca', 2, 'Before the garlic browns, add the olives, capers, tomato sauce, and chile peppers.'),
    ('wikibooks_spaghetti_alla_puttanesca', 3, 'Add 2–3 pinches of salt, mixing over high heat. Then lower the heat and allow to simmer for 15 to 20 minutes.'),
    ('wikibooks_spaghetti_alla_puttanesca', 4, 'Meanwhile, cook the spaghetti in salted water (at least 4 quarts of water per pound of spaghetti being cooked). Strain it when it''s al dente.'),
    ('wikibooks_spaghetti_alla_puttanesca', 5, 'Place pasta in a large serving bowl, and coat it with sauce. Then, sprinkle it with chopped parsley.'),
    ('wikibooks_spaghetti_alla_puttanesca', 6, 'Mix and serve hot.'),
    ('wikibooks_dinuguan_pork_blood_stew', 1, 'Place the pork in a 4-quart (560 ml) covered stove-top casserole dish and add the vinegar mixture. Bring to a boil and reduce the heat.'),
    ('wikibooks_dinuguan_pork_blood_stew', 2, 'Cook, covered, for about an hour, until the pork is tender. Make sure that the liquid doesn''t dry out. Add more water if necessary.'),
    ('wikibooks_dinuguan_pork_blood_stew', 3, 'Heat a frying pan and add the lard or oil.'),
    ('wikibooks_dinuguan_pork_blood_stew', 4, 'When the oil is hot enough, sauté the onion and garlic until the onion appears translucent. Remove from heat.'),
    ('wikibooks_dinuguan_pork_blood_stew', 5, 'Add the oil, garlic, and onion to the pork and continue cooking for 5 minutes.'),
    ('wikibooks_dinuguan_pork_blood_stew', 6, 'Purée the pork blood in a food processor.'),
    ('wikibooks_dinuguan_pork_blood_stew', 7, 'Add the blood to the pork gradually while stirring the mixture. Bring to a boil.'),
    ('wikibooks_dinuguan_pork_blood_stew', 8, 'Add the chopped pepper and simmer uncovered to reduce the sauce until desired thickness is achieved. Keep covered and serve hot.'),
    ('wikibooks_mozzarella_sticks', 1, 'Preheat deep fryer to 350°F (175°C).'),
    ('wikibooks_mozzarella_sticks', 2, 'Slice mozzarella into sticks 1–3 cm in diameter.'),
    ('wikibooks_mozzarella_sticks', 3, 'In a small bowl, whisk egg.'),
    ('wikibooks_mozzarella_sticks', 4, 'Fill another small bowl with bread crumbs.'),
    ('wikibooks_mozzarella_sticks', 5, 'Dip 3–4 sticks at a time into the egg.'),
    ('wikibooks_mozzarella_sticks', 6, 'Shake excess egg off sticks and place them in the bread crumbs.'),
    ('wikibooks_mozzarella_sticks', 7, 'Shake bowl of bread crumbs, evenly coating all sticks. Add more bread crumbs as needed.'),
    ('wikibooks_mozzarella_sticks', 8, 'Place coated sticks to the side and repeat for remaining sticks.'),
    ('wikibooks_mozzarella_sticks', 9, 'After all sticks have been coated, repeat the egg-dip and crumb-coat for each once more.'),
    ('wikibooks_mozzarella_sticks', 10, 'Place all sticks in fryer basket and submerge in 350°F oil.'),
    ('wikibooks_mozzarella_sticks', 11, 'Let sit for 30 seconds, gently rocking basket occasionally.'),
    ('wikibooks_mozzarella_sticks', 12, 'Lift basket and let cool for a few seconds. If cheese is not beginning to ooze out from half the sticks, re-submerge in oil for another 10–15 seconds, gently shaking the basket. Repeat until the cheese is just starting to ooze out.'),
    ('wikibooks_mozzarella_sticks', 13, 'Dump onto paper towel and pat off excess oil gently.'),
    ('wikibooks_mozzarella_sticks', 14, 'Serve hot.')
) as v(recipe_slug, step_number, instruction)
join public.recipes r on r.slug = v.recipe_slug;

